import java.util.*;

class Solution {
  public int minDayskVariants(int[][] points, int k) {
    // the best meeting cell lies inside the points' bounding box: try every cell there
    int best = Integer.MAX_VALUE;
    int[] dist = new int[points.length];
    for (int x = 1; x <= 100; x++)
      for (int y = 1; y <= 100; y++) {
        for (int i = 0; i < points.length; i++) dist[i] = Math.abs(points[i][0] - x) + Math.abs(points[i][1] - y);
        Arrays.sort(dist);
        best = Math.min(best, dist[k - 1]);
      }
    return best;
  }
}
